mapper.select:
select chan.* from ( select channels.*,count(channels.userAccessId) as subscribeNum from ( SELECT channel.*, info.last_name AS createUserLastName, info.first_name AS createUserFirstName, tags.id AS tag_id, tags.channel_id AS tag_channel_id, tags.type AS tag_type, tags.tag_text AS tag_text, ssubscribeNumUserAccess.user_id as userAccessId, subscribeNumPermission.subscribe_permission, subscribeNumPermission.channel_permission
,IF( IFNULL(( SELECT count(1) FROM gc_user_access_permission per LEFT JOIN gc_user_access acc ON acc.id = per.user_access_id WHERE JSON_CONTAINS( per.subscribe_permission, CONVERT ( channel.id, CHAR ))= 1 and acc.user_id = #{userId} and acc.master_id=#{masterId} GROUP BY acc.user_id ), 0 ) =0,0,1) AS followFlag/*区分自己订阅的还是小队默认绑定的*/
FROM pt_channel channel left join gc_user us on us.id = channel.create_user_id left join gc_user_info info on info.id = us.info_id left join pt_tags tags on tags.channel_id = channel.id LEFT JOIN gc_user_access_permission subscribeNumPermission ON JSON_CONTAINS(ifnull(subscribeNumPermission.subscribe_permission,'[]'), CONVERT ( channel.id, CHAR ))= 1 LEFT JOIN gc_user_access ssubscribeNumUserAccess on ssubscribeNumUserAccess.id = subscribeNumPermission.user_access_id WHERE 1 = 1 and level=0/*type为0查不是自己创建的channel，为1查询自己创建的channel*/ AND ssubscribeNumUserAccess.master_id =#{masterId} and channel.create_user_id != #{userId} GROUP BY channel.id,ssubscribeNumUserAccess.user_id
order by ssubscribeNumUserAccess.user_id = #{userId} desc
order by channel.create_time desc
) as channels group by channels.id order by channels.create_time desc ) as chan LEFT JOIN pt_channel_subscribe sub on chan.id = sub.channel_id and user_id = #{userId} where 1=1 AND (JSON_CONTAINS(ifnull(chan.subscribe_permission,'[]'), CONVERT ( chan.id, CHAR ))= 1 ) and chan.create_user_id != #{userId}
and chan.userAccessId = #{userId}
group by chan.id order by sub.create_time desc,chan.create_time desc

SELECT channel.*, access.id as code_id,access.id as code_id ,access.code as team_codename,subscribeAccess.id as subscribe_code_id, subscribeAccess.code as subscribe_code_name,subscribeAccess.group_name as groupName,access.group_name as accessGroupName FROM pt_channel channel left join gc_access access on JSON_CONTAINS(access.channel_json, CONVERT(channel.id, CHAR))=1 left join gc_access subscribeAccess on JSON_CONTAINS(subscribeAccess.subscribe_json, CONVERT(channel.id, CHAR))=1 LEFT JOIN gc_user_access_permission permission ON JSON_CONTAINS( permission.subscribe_permission, CONVERT ( channel.id, CHAR ))= 1 LEFT JOIN gc_user_access userAccess on userAccess.id = permission.user_access_id where 1=1 and channel.id in
#{channelId}
and userAccess.master_id = #{masterId} and userAccess.user_id = #{userId} group by channel.id,access.id,subscribeAccess.id

SELECT channel.*,us.username as channel_create_user_username,us.id as channel_create_uid, GROUP_CONCAT(userAccess.user_id) as subscribeUserIds, info.last_name as userInfo_lastName,info.first_name as userInfo_firstName,subscribe_us.id as subscribe_user_id,subscribe_us.username as subscribe_user_username,subscribe_info.last_name as subscribe_userInfo_lastName, subscribe_info.first_name as subscribe_userInfo_firstName,subscribe_info.avatar_file_id as subscribe_userInfo_avatar_file_id, access.id as code_id,access.id as code_id ,access.code as team_codename,subscribeAccess.id as subscribe_code_id, subscribeAccess.code as subscribe_code_name,subscribeAccess.group_name as groupName,access.group_name as accessGroupName FROM pt_channel channel left join gc_user us on us.id = channel.create_user_id left join gc_user_info info on info.id = us.info_id left join pt_channel sec on sec.fid = channel.id left join pt_channel_subscribe sub on sub.channel_id = channel.id left join (SELECT u.* FROM pt_channel_subscribe sub LEFT JOIN gc_user u ON u.id = sub.user_id ORDER BY sub.create_time desc LIMIT 6 )subscribe_us on subscribe_us.id = sub.user_id left join gc_user_info subscribe_info on subscribe_info.id = subscribe_us.info_id left join gc_access access on JSON_CONTAINS(access.channel_json, CONVERT(channel.id, CHAR))=1 left join gc_access subscribeAccess on JSON_CONTAINS(subscribeAccess.subscribe_json, CONVERT(channel.id, CHAR))=1 LEFT JOIN gc_user_access_permission permission ON JSON_CONTAINS( permission.subscribe_permission, CONVERT ( channel.id, CHAR ))= 1 LEFT JOIN gc_user_access userAccess on userAccess.id = permission.user_access_id WHERE 1=1
and channel.id = #{channelId}
and channel.channel_slug = #{slug}
and channel.master_id = #{masterId}
group by channel.id ,sec.id,sub.id,subscribe_us.id,subscribe_info.id,access.id,subscribeAccess.id order by sec.create_time ${order}

SELECT file.*,
u.username as channel_create_user_username, u.id as channel_create_uid, info.last_name as createUserLastName, info.first_name as createUserFirstName, info.avatar_file_id as userInfo_avatar_file_id,
content.id AS ptChannelContentId FROM sys_file file right JOIN pt_channel_content content on content.file_id=file.id right JOIN( select channel.* from pt_channel channel LEFT JOIN pt_channel section on section.fid = channel.id where channel.id = #{sectionId}
union select section.* from pt_channel channel LEFT JOIN pt_channel section on section.fid = channel.id where section.fid = #{sectionId}
)channel on channel.id = content.channel_id left join gc_user u on u.id = file.upload_uid left join gc_user_info info on info.id = u.info_id
WHERE 1 = 1 and file.id is not null
AND file.NAME LIKE concat('%',#{searchName},'%')
group by file.id
order by file.create_time ${order}
order by content.create_time asc

select * from pt_channel where 1=1

    and fid = (select id from pt_channel where channel_slug = #{slug} and master_id = #{masterId})


    and fid=#{channelId}


    and master_id = #{masterId}

order by create_time ${order}

select access.*,GROUP_CONCAT(access.subscribe_json) as subscribeAccessIds from gc_access access
                                                                                   LEFT JOIN gc_user_access ua on ua.access_id = access.id
where ua.user_id = #{userId} and ua.master_id=#{masterId}

select ch.*, u.username as channel_create_user_username,u.id as channel_create_uid,info.last_name as createUserLastName, info.first_name as createUserFirstName,tags.id as tag_id,tags.channel_id as tag_channel_id,tags.type as tag_type,tags.tag_text as tag_text, group_concat(tags.tag_text) as channelTags, info.avatar_file_id as userInfo_avatar_file_id from pt_channel ch left join gc_access ac ON JSON_CONTAINS(ac.channel_json, CONVERT(ch.ID, CHAR))=1 left join gc_user_access ua on ac.id = ua.access_id and ac.master_id = ua.master_id left join gc_user u on u.id = ch.create_user_id left join gc_user_info info on info.id = u.info_id left join sys_file file on file.id = info.avatar_file_id left join pt_tags tags on tags.channel_id = ch.id where 1=1 and ua.user_id = #{userId} and ua.master_id = #{userId}
and ch.id not in
#{channelId}
and ch.channel_name like concat('%',#{name},'%')
and ch.master_id = #{masterId} and ch.level = 0 group by ch.id order by ch.create_time desc

select ch.*, u.username as channel_create_user_username,u.id as channel_create_uid,info.last_name as createUserLastName, info.first_name as createUserFirstName,tags.id as tag_id,tags.channel_id as tag_channel_id,tags.type as tag_type,tags.tag_text as tag_text, group_concat(tags.tag_text) as channelTags, info.avatar_file_id as userInfo_avatar_file_id from pt_channel ch left join gc_user u on u.id = ch.create_user_id left join gc_user_info info on info.id = u.info_id left join sys_file file on file.id = info.avatar_file_id left join pt_tags tags on tags.channel_id = ch.id where 1=1
and ch.id not in
#{channelId}
and ch.channel_name like concat('%',#{name},'%')
and ch.create_user_id = #{userId}
and ch.master_id = #{masterId} and ch.level = 0 group by ch.id order by ch.create_time desc

select b.channelSlug as channel_slug, count(b.userid) as subscribeUserIds from ( select channel.id as id, channel.channel_slug as channelSlug, userAccess.user_id as userid from pt_channel channel LEFT JOIN gc_user_access_permission permission ON JSON_CONTAINS( permission.subscribe_permission, CONVERT ( channel.id, CHAR ))= 1 LEFT JOIN gc_user_access userAccess on userAccess.id = permission.user_access_id where 1=1 and channel.channel_slug in
#{slug}
and channel.master_id = #{masterId} group by channel.channel_slug,userAccess.user_id ) as b group by b.channelSlug

select * from ( select channels.*,count(channels.userAccessId) as subscribeNum from ( SELECT channel.*, info.last_name AS createUserLastName, info.first_name AS createUserFirstName, tags.id AS tag_id, tags.channel_id AS tag_channel_id, tags.type AS tag_type, tags.tag_text AS tag_text, ssubscribeNumUserAccess.user_id as userAccessId, subscribeNumPermission.subscribe_permission, subscribeNumPermission.channel_permission
,IF( IFNULL((
SELECT count(1) FROM gc_user_access_permission per LEFT JOIN gc_user_access acc ON acc.id = per.user_access_id WHERE JSON_CONTAINS( per.subscribe_permission, CONVERT ( channel.id, CHAR ))= 1 and acc.user_id = #{userId} and acc.master_id=#{masterId} GROUP BY acc.user_id
), 0 ) =0,0,1) AS followFlag/*区分自己订阅的还是小队默认绑定的*/
FROM pt_channel channel LEFT JOIN pt_channel_subscribe sub on channel.id = sub.channel_id left join gc_user us on us.id = channel.create_user_id left join gc_user_info info on info.id = us.info_id left join pt_tags tags on tags.channel_id = channel.id LEFT JOIN gc_user_access_permission subscribeNumPermission ON JSON_CONTAINS( JSON_MERGE(ifnull(subscribeNumPermission.subscribe_permission,'[]'),ifnull(subscribeNumPermission.channel_permission,'[]')), CONVERT ( channel.id, CHAR ))= 1 LEFT JOIN gc_user_access ssubscribeNumUserAccess on ssubscribeNumUserAccess.id = subscribeNumPermission.user_access_id WHERE 1 = 1 and level=0/*type为0查不是自己创建的channel，为1查询自己创建的channel*/ AND ssubscribeNumUserAccess.master_id =#{masterId}
and concat(channel.channel_name,channel.channel_slug) like concat('%',#{channelName},'%')
or (channel.create_user_id = #{userId} and channel.master_id = #{masterId})
/*公共*/
or (channel.visible_flag = 3 and channel.master_id = #{masterId} and channel.create_user_id != #{userId})
or (channel.visible_flag = 3 and channel.master_id = #{masterId} and channel.create_user_id = #{userId})
GROUP BY channel.id,ssubscribeNumUserAccess.user_id
order by ssubscribeNumUserAccess.user_id = #{userId} desc
order by channel.create_time desc
) as channels group by channels.id order by channels.create_time desc ) as chan where 1=1
AND (JSON_CONTAINS( chan.subscribe_permission, CONVERT ( chan.id, CHAR )) = 1 )
and chan.userAccessId = #{userId}
OR ( chan.create_user_id = #{userId} AND chan.LEVEL = 0 AND chan.master_id = #{masterId}) or (chan.visible_flag = 3 and chan.master_id = #{masterId} and chan.create_user_id = #{userId})
AND (JSON_CONTAINS(chan.subscribe_permission, CONVERT ( chan.id, CHAR ))= 0 OR JSON_CONTAINS(chan.subscribe_permission, CONVERT ( chan.id, CHAR )) IS NULL ) AND JSON_CONTAINS(chan.channel_permission, CONVERT ( chan.id, CHAR ))= 1 and chan.create_user_id != #{userId}
and chan.userAccessId = #{userId}
/*公共*/ or (chan.visible_flag = 3 and chan.master_id = #{masterId} and chan.create_user_id != #{userId})
and concat(chan.channel_name,chan.channel_slug) like concat('%',#{channelName},'%')
